// `@apply` only takes utilities in Tailwind v4, so the shared building blocks are declared as such.
@utility input-disable {
  @apply bg-layer-3 text-secondary;
}

@utility base-button {
  @apply flex flex-row items-center px-3 py-2;
  @apply rounded border border-solid border-transparent text-sm;

  min-width: 38px;
  min-height: 38px;
}

@utility base-button-disable {
  @apply pointer-events-none text-controls-disable bg-controls-disable;
}

// Shared by `.input` and by the AG Grid fields that look like it: `@apply` cannot take a class in Tailwind v4.
@mixin input-field {
  @apply border border-solid border-primary rounded outline-0;
  @apply bg-transparent text-sm truncate;
  @apply px-3 py-2;

  &:not(:placeholder-shown) {
    @apply text-primary;
  }

  &:hover {
    @apply border-hover;
  }

  &:focus,
  &:focus-within {
    @apply border-accent-primary;
  }

  &:disabled {
    @apply bg-layer-3 text-secondary;
  }
}

// Same reason as `input-field`: the grid buttons reuse these through `@include`.
@mixin button-primary {
  @apply base-button bg-controls-accent text-controls-primary;

  &:hover,
  &:focus {
    @apply bg-controls-accent-hover;
  }

  &:focus {
    @apply border-hover;
  }
}

@mixin button-secondary {
  @apply base-button bg-transparent text-primary;
  @apply border-primary;

  &:hover,
  &:focus {
    @apply bg-layer-4;
  }

  &:focus {
    @apply border-hover;
  }

  &:disabled {
    @apply base-button-disable;
  }
}

@layer components {
  // TODO: remove after fixing style in UI kit
  .input {
    @include input-field;
  }

  .primary {
    @include button-primary;
  }

  .secondary {
    @include button-secondary;
  }
}

// The file manager grid is framed by a 1px border with an 8px radius (replaces the library's rounded-xl + shadow).
.file-manager-grid {
  @apply border border-solid border-tertiary rounded-lg overflow-hidden !shadow-none;
}

// The file manager grid design draws row dividers at half weight (header divider stays 1px).
.file-manager-grid .ag-root-wrapper .ag-row {
  border-bottom-width: 0.5px;
}

.ag-root-wrapper {
  .ag-row {
    @apply border-b border-tertiary;
  }

  .ag-root-wrapper-body {
    @apply h-auto;
  }

  .ag-filter-wrapper {
    .ag-input-field-input.ag-text-field-input,
    .ag-input-field-input.ag-number-field-input,
    .ag-picker-field-wrapper.ag-picker-collapsed,
    .ag-picker-field-wrapper.ag-picker-expanded {
      @include input-field;
    }

    .ag-input-field-input.ag-text-field-input,
    .ag-input-field-input.ag-input-field-input {
      @apply pl-5;
    }

    .ag-filter-apply-panel-button.ag-button {
      @apply base-button;
      &[data-ref='applyFilterButton'] {
        @include button-primary;
      }

      &[data-ref='resetFilterButton'] {
        @include button-secondary;
      }
    }
  }

  @apply overflow-x-auto;
  .ag-header {
    @apply border-b border-tertiary;
    .ag-header-cell.align-right {
      .ag-header-cell-label {
        @apply justify-end;
      }
    }
    .ag-header-viewport,
    .ag-pinned-left-header {
      .ag-floating-filter {
        input {
          @include input-field;
          @apply m-0 p-0 px-2;
          height: 24px !important;
        }
      }
      // A filter row with no input (see EmptyFloatingFilter): drop the empty body so the button
      // centres in the cell instead of hanging off its right edge.
      .ag-floating-filter:has(.ag-grid-filter-button-only) {
        .ag-floating-filter-body {
          @apply hidden;
        }

        .ag-floating-filter-button {
          @apply flex h-full w-full items-center justify-center;
          margin: 0;
        }
      }
    }
  }

  .ag-cell {
    user-select: text;
    @apply flex items-center;
    &.ag-grid-no-border,
    &.ag-cell-focus {
      @apply border-0;
    }

    &.column-divider:not(:last-child) {
      @apply border-0 border-r border-solid border-tertiary;
    }

    &.align-right {
      @apply justify-end;
    }
  }
  .ag-cell.ag-cell-first-right-pinned:not(
      .ag-cell-range-left,
      .ag-cell-range-single-cell,
      .ag-cell-focus:not(.ag-cell-range-selected):focus-within
    ) {
    @apply border-0;
  }
  .ag-error-row {
    @apply bg-error;
    #editable-cell-renderer {
      @apply border-error;
    }
    &.ag-error-border {
      @apply border border-error;
      @apply cursor-pointer;
    }
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
